import sys
from collections import defaultdict

def is_valid_date(date):
    day = int(date[:2])
    month = int(date[3:5])
    year = int(date[6:10])
    if not (2013 <= year <= 2015 and 1 <= month <= 12):
        return False
    if month == 2:
        return 1 <= day <= 28
    elif month in [4, 6, 9, 11]:
        return 1 <= day <= 30
    else:
        return 1 <= day <= 31

def find_apocalypse_date(prophesy):
    date_counts = defaultdict(int)
    n = len(prophesy)
    for i in range(n - 9):
        candidate = prophesy[i:i+10]
        if candidate[2] == '-' and candidate[5] == '-':
            date = candidate
            if is_valid_date(date):
                date_counts[date] += 1
    if not date_counts:
        return None
    max_count = max(date_counts.values())
    apocalypse_dates = [date for date, count in date_counts.items() if count == max_count]
    return min(apocalypse_dates)

def main():
    prophesy = sys.stdin.readline().strip()
    apocalypse_date = find_apocalypse_date(prophesy)
    print(apocalypse_date)

if __name__ == "__main__":
